import { useState } from 'react';

import cn from 'clsx';
import { useNavigate } from 'react-router-dom';

import { err, success } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

import { addOrUpdateBaseRoute } from '../@services/routes.service';
import { IRouteAddOrUpdateDTO } from '../@types/DTO/routes.dto.types';

const RouteAdd = () => {
  const [formData, setFormData] = useState({
    id: 0,
    name: '',
    desc: '',
  });

  const navigate = useNavigate();

  const submitFormHandler = (e: React.FormEvent) => {
    e.preventDefault();

    addOrUpdateBaseRoute(formData)
      .then((id) => {
        success('Маршрут успешно добавлен');
        navigate(`/routes/${id}/edit`);
      })
      .catch((error) => {
        err(error || 'Ошибка');
      });
  };

  function handleInputChange<T extends keyof IRouteAddOrUpdateDTO>(
    field: keyof IRouteAddOrUpdateDTO,
  ) {
    return (value: IRouteAddOrUpdateDTO[T]) => {
      setFormData((fd) => ({
        ...fd,
        [field]: value,
      }));
    };
  }

  return (
    <PohContainer>
      <PohRow>
        <PohCol
          lg={{ span: 8, offset: 2 }}
          md={{ span: 10, offset: 1 }}
          sm={{ span: 12, offset: 0 }}
        >
          <PohRow>
            <PohCol sm={2} />
            <PohCol sm={10}>
              <h2>Новый маршрут</h2>
            </PohCol>
          </PohRow>
        </PohCol>
      </PohRow>
      <PohRow>
        <PohCol
          lg={{ span: 8, offset: 2 }}
          md={{ span: 10, offset: 1 }}
          sm={{ span: 12, offset: 0 }}
        >
          <div>
            <form onSubmit={submitFormHandler} className={cn('mt-4', 'qa-hiking-base-info-form')}>
              <PohRow className="mb-2">
                <PohCol sm={12}>
                  <PohInput
                    horizontal
                    label="Название"
                    placeholder="Название маршрута"
                    required
                    value={formData.name}
                    name="name"
                    id="name"
                    onChange={handleInputChange('name')}
                    autoFocus
                  />
                </PohCol>
              </PohRow>
              <PohRow className="mb-2">
                <PohCol sm={12}>
                  <PohInput
                    horizontal
                    type={InputTypes.textarea}
                    label="Идея"
                    placeholder="Описание идеи маршрута"
                    required
                    value={formData.desc}
                    name="desc"
                    id="desc"
                    onChange={handleInputChange('desc')}
                  />
                </PohCol>
              </PohRow>
              <PohRow className="mb-4 mt-2">
                <PohCol sm={2} />
                <PohCol sm={10}>
                  <PohButton
                    variant={ButtonVariant.Primary}
                    onClick={() => {}}
                    className="w-100"
                    type="submit"
                  >
                    Создать и открыть в редакторе
                  </PohButton>
                </PohCol>
              </PohRow>
            </form>
          </div>
        </PohCol>
      </PohRow>
    </PohContainer>
  );
};

export default RouteAdd;
